        mid = (left + right) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] > target:
            return binary_search_rec(arr, left, mid - 1, target)
        else:
            return binary_search_rec(arr, mid + 1, right, target)
    return -1

